import React, { useState, useEffect } from 'react';
import AddTrip from './components/AddTrip';
import JoinTrip from './components/JoinTrip';
import Dashboard from './components/Dashboard';
import api from './api';

function App() {
  const [trip, setTrip] = useState(null);
  const [expenses, setExpenses] = useState([]);

  useEffect(() => {
    // Load last accessed trip from localStorage
    const savedTripId = localStorage.getItem('currentTripId');
    if (savedTripId) {
      loadTrip(savedTripId);
    }
  }, []);

  const loadTrip = async (tripId) => {
    try {
      const response = await api.get(`/trips/${tripId}`);
      setTrip(response.data);
      const expensesResponse = await api.get(`/trips/${tripId}/expenses`);
      setExpenses(expensesResponse.data);
    } catch (error) {
      console.error('Error loading trip:', error);
    }
  };

  const handleCreateTrip = async (tripData) => {
    try {
      const response = await api.post('/trips', tripData);
      setTrip(response.data);
      localStorage.setItem('currentTripId', response.data._id);
    } catch (error) {
      console.error('Error creating trip:', error);
    }
  };

  const handleJoinTrip = (tripData) => {
    setTrip(tripData);
    localStorage.setItem('currentTripId', tripData._id);
  };

  const styles = {
    container: {
      padding: '20px',
      maxWidth: '1200px',
      margin: '0 auto',
      fontFamily: 'Arial, sans-serif'
    },
    header: {
      textAlign: 'center',
      color: '#333',
      marginBottom: '30px'
    }
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.header}>Trip Expense Splitter</h1>
      {!trip ? (
        <div>
          <AddTrip setTrip={handleCreateTrip} />
          <JoinTrip onJoinTrip={handleJoinTrip} />
        </div>
      ) : (
        <div>
          <div style={{ marginBottom: '20px', padding: '10px', background: '#f0f0f0' }}>
            <p>Share Code: <strong>{trip.shareCode}</strong></p>
            <small>Share this code with others to let them join this trip</small>
          </div>
          <Dashboard 
            trip={trip} 
            setTrip={setTrip} 
            expenses={expenses} 
            setExpenses={setExpenses} 
          />
        </div>
      )}
    </div>
  );
}

export default App;
